<?php
require __DIR__.'/auth.php'; require_login();
$api=rtrim(getenv('MONITOR_API_URL')?:'http://api:3000','/');
function api_get(string $path):array{global $api;$ch=curl_init($api.$path);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>8,CURLOPT_HTTPHEADER=>['Accept: application/json']]);$body=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($body===false||$code>=400)return ['error'=>'API unavailable','status'=>$code];return json_decode($body,true)?:[];}
$summary=api_get('/api/v1/dashboard/summary');$hosts=api_get('/api/v1/hosts');$alerts=api_get('/api/v1/alerts');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="30"><title>Infrastructure Monitoring</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand text-white" href="index.php">Infrastructure Monitoring</a><div class="d-flex align-items-center gap-2"><span class="text-white small"><?=e($_SESSION['user']['username'])?> (<?=e($_SESSION['user']['role'])?>)</span><?php if($_SESSION['user']['role']==='ADMIN'):?><a class="btn btn-outline-light btn-sm" href="admin.php">Admin</a><?php endif;?><a class="btn btn-outline-light btn-sm" href="logout.php">Logout</a></div></div></nav><main class="container-fluid p-4"><div class="row g-3 mb-4"><?php foreach([['Total Hosts',$summary['hosts']['total']??0,''],['Online',$summary['hosts']['online']??0,'text-success'],['Warning',$summary['hosts']['warning']??0,'text-warning'],['Critical',$summary['hosts']['critical']??0,'text-danger'],['Open Alerts',$summary['alerts']['open_alerts']??0,'text-danger']] as $x):?><div class="col"><div class="card shadow-sm"><div class="card-body"><small><?=$x[0]?></small><h2 class="<?=$x[2]?>"><?=e($x[1])?></h2></div></div></div><?php endforeach;?></div><div class="card shadow-sm mb-4"><div class="card-header fw-semibold">Hosts</div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Name</th><th>Hostname</th><th>IP</th><th>Status</th><th>Last Seen</th></tr></thead><tbody><?php foreach(($hosts??[]) as $h):$cls=$h['status']==='ONLINE'?'success':($h['status']==='CRITICAL'||$h['status']==='OFFLINE'?'danger':'warning');?><tr style="cursor:pointer" onclick="location.href='host.php?id=<?=e($h['id'])?>'"><td><a href="host.php?id=<?=e($h['id'])?>"><?=e($h['name'])?></a></td><td><?=e($h['hostname'])?></td><td><?=e($h['ip_address']??'')?></td><td><span class="badge text-bg-<?=$cls?>"><?=e($h['status'])?></span></td><td><?=e($h['last_seen'])?></td></tr><?php endforeach;?></tbody></table></div></div><div class="card shadow-sm"><div class="card-header fw-semibold">Recent Alerts</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Host</th><th>Severity</th><th>Status</th><th>Title</th><th>Started</th></tr></thead><tbody><?php foreach(($alerts??[]) as $a):?><tr><td><?=e($a['host_name'])?></td><td><?=e($a['severity'])?></td><td><?=e($a['status'])?></td><td><?=e($a['title'])?></td><td><?=e($a['started_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>